schema:
CREATE TABLE hubs (hub_code TEXT NOT NULL PRIMARY KEY, region TEXT);
CREATE TABLE carriers (carrier_id TEXT NOT NULL PRIMARY KEY, service_tier TEXT);
CREATE TABLE transfers (source_code TEXT NOT NULL, source_code2 TEXT NOT NULL, carrier_id TEXT, PRIMARY KEY (source_code, source_code2), FOREIGN KEY (source_code) REFERENCES hubs(hub_code), FOREIGN KEY (source_code2) REFERENCES hubs(hub_code), FOREIGN KEY (carrier_id) REFERENCES carriers(carrier_id));
